(function(){
  'use strict';const V=ExplorationVisuals,KEY='sumyeon-visual-review-1',gallery=document.getElementById('gallery'),candidate=document.getElementById('candidate'),notes=document.getElementById('notes'),status=document.getElementById('status');
  for(const [id,p]of Object.entries(V.PLACES)){const article=document.createElement('article');article.className='place';article.dataset.place=id;article.innerHTML=`<div class="art-frame"><img class="background" src="assets/exploration/hospital-${id}-bg.svg" alt="${p.name} 배경"><img class="props" src="assets/exploration/hospital-${id}-props.svg" alt=""><div class="sample-ui" hidden><span>조사 · 시간 −2 / 북쪽 ↑</span></div></div><h2></h2><p></p>`;article.querySelector('h2').textContent=p.name;article.querySelector('p').textContent=p.description;gallery.append(article);candidate.add(new Option(p.name,id));}
  document.querySelectorAll('.controls input').forEach(input=>input.addEventListener('change',()=>{const selector=input.id==='ui'?'.sample-ui':'.'+input.id;document.querySelectorAll(selector).forEach(node=>node.hidden=!input.checked);}));
  const reviewStartedAt=new Date().toISOString(),reviewStarted=performance.now();
  let record={version:1,candidate:null,approved:false,notes:'',recordedAt:null};try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Object.keys(V.PLACES).includes(saved.candidate)){record={...record,...saved,approved:false};candidate.value=record.candidate;notes.value=String(record.notes||'').slice(0,2000);}}catch{}
  function capture(){return {version:1,candidate:candidate.value||null,approved:false,notes:notes.value,recordedAt:new Date().toISOString(),reviewStartedAt,reviewElapsedMilliseconds:Math.round(performance.now()-reviewStarted),scope:'Placeholder anchor candidate; explicit human art approval remains separate'};}
  document.getElementById('save').addEventListener('click',()=>{record=capture();try{localStorage.setItem(KEY,JSON.stringify(record));status.textContent='후보 기록을 저장했습니다. 아트 승인은 아직 완료되지 않았습니다.';}catch{status.textContent='저장하지 못했습니다. 검토 기록을 파일로 내려받을 수 있습니다.';}});
  document.getElementById('export').addEventListener('click',()=>{const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(capture(),null,2)],{type:'application/json'}));link.href=url;link.download='sumyeon-visual-anchor-review.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
  fetch('assets/exploration/manifest.json').then(r=>{if(!r.ok)throw Error('manifest');return r.json();}).then(m=>{document.getElementById('metadata').textContent=JSON.stringify({status:m.status,anchorApproval:m.userApprovedAnchor,tool:m.production.tool,workflow:m.production.workflowVersion,camera:m.camera,palette:m.palette,assetCount:m.assets.length,generationMilliseconds:m.production.generationMilliseconds,promptModules:m.promptModules},null,2);}).catch(()=>{document.getElementById('metadata').textContent='자산 매니페스트를 읽지 못했습니다.';});
})();
